    for sy in (1, -1):
        for sx in (1, -1):
            for swap in (False, True):
                pts = [(y * sy, x * sx) for y, x in cells]
                if swap:
                    pts = [(x, y) for y, x in pts]
                my = min(y for y, x in pts)
                mx = min(x for y, x in pts)
                variants.add(frozenset((y-my, x-mx) for y, x in pts))
    return variants


def _components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    return bg, comps


def _contains(host, variants):
    for shape in variants:
        for y, x in host:
            if all((y + dy, x + dx) in host for dy, dx in shape):
                return True
    return False


def transform(grid):
    bg, comps = _components(grid)
    out = [row[:] for row in grid]
    # Find congruent components that are both instances of a motif embedded
    # in a third, larger component; recolor the motif instances to that host.
    motifs = {}
    for i, (color, cells) in enumerate(comps):
        canonical = min(tuple(sorted(v)) for v in _variants(cells))
        motifs.setdefault(canonical, []).append(i)
    proposals = []
    for ids in motifs.values():
        colors = {comps[i][0] for i in ids}
        if len(ids) < 2 or len(colors) < 2:
            continue
        motif_size = len(comps[ids[0]][1])
        for j, (host_color, host) in enumerate(comps):
            if host_color in colors or len(host) <= motif_size:
                continue
            variants = _variants(comps[ids[0]][1])
            if _contains(host, variants):
                proposals.append((motif_size, -len(host), host_color, ids))
    if proposals:
        _, _, host_color, ids = min(proposals, key=lambda item: (item[0], item[1]))
        for i in ids:
            color, cells = comps[i]
            for r, c in cells:
                out[r][c] = host_color
    return out


